"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import styles from "../styles/copy-button.module.css";

export interface CopyButtonProps {
  /** Text written to the clipboard */
  text?: string;
  /** Button label before copying */
  label?: string;
  /** Button label after a successful copy */
  copiedLabel?: string;
  /** Milliseconds before the button resets to its idle state */
  resetDelay?: number;
  /** Visual style */
  variant?: "default" | "outline" | "ghost";
  /** Size preset */
  size?: "sm" | "md" | "lg";
  /** Render the text in a code field beside the button */
  showValue?: boolean;
  /** Hide the visible label and show only the morphing icon */
  iconOnly?: boolean;
  /** Color of the check mark and copied state */
  accentColor?: string;
  /** Disable the button */
  disabled?: boolean;
  /** Called after the text has been copied */
  onCopy?: (text: string) => void;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

async function writeClipboard(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    // fall through to the legacy path
  }
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch {
    return false;
  }
}

export function CopyButton({
  text = "npx motionfoundry add copy-button",
  label = "Copy",
  copiedLabel = "Copied",
  resetDelay = 2000,
  variant = "outline",
  size = "md",
  showValue = true,
  iconOnly = false,
  accentColor = "#22c55e",
  disabled = false,
  onCopy,
  className = "",
  style,
}: CopyButtonProps) {
  const reduce = useReducedMotion();
  const [copied, setCopied] = React.useState(false);
  const timer = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  React.useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current);
  }, []);

  const copy = async () => {
    if (disabled) return;
    const ok = await writeClipboard(text);
    if (!ok) return;
    setCopied(true);
    onCopy?.(text);
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setCopied(false), Math.max(300, resetDelay));
  };

  const spring = reduce ? { duration: 0.1 } : { type: "spring" as const, stiffness: 520, damping: 28 };
  const iconMotion = reduce
    ? { initial: { opacity: 0 }, animate: { opacity: 1 }, exit: { opacity: 0 } }
    : { initial: { opacity: 0, scale: 0.4, rotate: -45 }, animate: { opacity: 1, scale: 1, rotate: 0 }, exit: { opacity: 0, scale: 0.4, rotate: 45 } };

  return (
    <div
      className={[styles.root, styles[size], showValue ? styles.withValue : "", className].filter(Boolean).join(" ")}
      style={{ "--mf-cb-accent": accentColor, ...style } as React.CSSProperties}
      data-copied={copied || undefined}
    >
      {showValue ? (
        <code className={styles.value} title={text}>
          <span className={styles.prompt} aria-hidden="true">
            $
          </span>
          {text}
        </code>
      ) : null}
      <button
        type="button"
        disabled={disabled}
        onClick={copy}
        aria-label={iconOnly || showValue ? (copied ? copiedLabel : `${label}${showValue ? " command" : ""}`) : undefined}
        className={`${styles.button} ${styles[variant]} ${iconOnly ? styles.iconOnly : ""}`.trim()}
      >
        <span className={styles.icon} aria-hidden="true">
          <AnimatePresence initial={false} mode="popLayout">
            {copied ? (
              <motion.svg key="check" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.25" strokeLinecap="round" strokeLinejoin="round" className={styles.check} {...iconMotion} transition={spring}>
                <motion.path d="M5 12.5l4.5 4.5L19 7" initial={{ pathLength: reduce ? 1 : 0 }} animate={{ pathLength: 1 }} transition={{ duration: reduce ? 0 : 0.28, delay: reduce ? 0 : 0.06 }} />
              </motion.svg>
            ) : (
              <motion.svg key="copy" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...iconMotion} transition={spring}>
                <rect x="9" y="9" width="12" height="12" rx="2" />
                <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
              </motion.svg>
            )}
          </AnimatePresence>
        </span>
        {iconOnly ? null : (
          <span className={styles.labelSlot} aria-hidden={showValue || undefined}>
            <span className={styles.sizer} aria-hidden="true">
              {label}
            </span>
            <span className={styles.sizer} aria-hidden="true">
              {copiedLabel}
            </span>
            <AnimatePresence initial={false} mode="popLayout">
              <motion.span
                key={copied ? "copied" : "idle"}
                className={styles.label}
                initial={reduce ? { opacity: 0 } : { opacity: 0, y: 8, filter: "blur(2px)" }}
                animate={reduce ? { opacity: 1 } : { opacity: 1, y: 0, filter: "blur(0px)" }}
                exit={reduce ? { opacity: 0 } : { opacity: 0, y: -8, filter: "blur(2px)" }}
                transition={{ duration: reduce ? 0.1 : 0.2, ease: [0.16, 1, 0.3, 1] }}
              >
                {copied ? copiedLabel : label}
              </motion.span>
            </AnimatePresence>
          </span>
        )}
      </button>
      <span className={styles.srOnly} role="status" aria-live="polite">
        {copied ? `${copiedLabel} to clipboard` : ""}
      </span>
    </div>
  );
}

.root {
  --mf-cb-h: 2.375rem;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  max-width: 100%;
  color: var(--mf-fg, #f4f4f6);
  font-size: 0.875rem;
}

.sm {
  --mf-cb-h: 2rem;
  font-size: 0.8125rem;
}

.md {
  --mf-cb-h: 2.375rem;
}

.lg {
  --mf-cb-h: 2.75rem;
  font-size: 0.9375rem;
}

.withValue {
  padding: 0.3125rem 0.3125rem 0.3125rem 0.875rem;
  border-radius: 0.75rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  transition: border-color 200ms ease, box-shadow 200ms ease;
}

.withValue[data-copied] {
  border-color: color-mix(in srgb, var(--mf-cb-accent, #22c55e) 45%, var(--mf-border, #2e2e38));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--mf-cb-accent, #22c55e) 14%, transparent);
}

.value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.92em;
  color: var(--mf-fg, #f4f4f6);
}

.prompt {
  margin-right: 0.625em;
  color: var(--mf-subtle, #71717a);
  user-select: none;
}

.button {
  position: relative;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4375rem;
  height: var(--mf-cb-h);
  padding: 0 0.875rem;
  border: 1px solid transparent;
  border-radius: 0.5rem;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, transform 180ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

.withValue .button {
  height: calc(var(--mf-cb-h) - 0.375rem);
}

.button:active:not(:disabled) {
  transform: scale(0.95);
}

.button:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 2px;
}

.button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.iconOnly {
  width: var(--mf-cb-h);
  padding: 0;
}

.withValue .iconOnly {
  width: calc(var(--mf-cb-h) - 0.375rem);
}

.default {
  background-color: var(--mf-fg, #f4f4f6);
  color: var(--mf-bg, #09090b);
}

.default:hover:not(:disabled) {
  opacity: 0.9;
}

.outline {
  background-color: var(--mf-surface-raised, #1b1b22);
  border-color: var(--mf-border, #2e2e38);
  color: var(--mf-fg, #f4f4f6);
}

.outline:hover:not(:disabled) {
  border-color: var(--mf-border-strong, #52525b);
}

.ghost {
  background-color: transparent;
  color: var(--mf-muted, #a1a1aa);
}

.ghost:hover:not(:disabled) {
  background-color: var(--mf-surface-raised, #1b1b22);
  color: var(--mf-fg, #f4f4f6);
}

.root[data-copied] .outline,
.root[data-copied] .ghost {
  color: var(--mf-cb-accent, #22c55e);
  border-color: color-mix(in srgb, var(--mf-cb-accent, #22c55e) 40%, transparent);
}

.root[data-copied] .default {
  background-color: var(--mf-cb-accent, #22c55e);
  color: #ffffff;
}

.icon {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 1rem;
  height: 1rem;
}

.icon svg {
  width: 100%;
  height: 100%;
}

.labelSlot {
  position: relative;
  display: inline-grid;
  text-align: left;
}

.labelSlot > * {
  grid-area: 1 / 1;
}

.sizer {
  visibility: hidden;
}

.label {
  display: inline-block;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .button,
  .withValue {
    transition: none;
  }

  .button:active:not(:disabled) {
    transform: none;
  }
}

