"use client";

import { AnimatePresence, motion } from "motion/react";
import { useState } from "react";

export function CopyButtonTailwind({ text = "npx motionfoundry add copy-button" }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    await navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };
  return (
    <div className="inline-flex items-center gap-3 rounded-xl border border-zinc-800 bg-zinc-900 py-1.5 pl-3.5 pr-1.5">
      <code className="font-mono text-sm text-zinc-100"><span className="mr-2 text-zinc-500">$</span>{text}</code>
      <button type="button" onClick={copy} aria-label={copied ? "Copied" : "Copy command"} className={`inline-flex h-8 items-center gap-1.5 rounded-lg border px-3 text-sm font-medium transition active:scale-95 ${copied ? "border-green-500/40 text-green-500" : "border-zinc-800 bg-zinc-800 text-zinc-100"}`}>
        <AnimatePresence initial={false} mode="popLayout">
          <motion.svg key={String(copied)} initial={{ scale: 0.4, rotate: -45, opacity: 0 }} animate={{ scale: 1, rotate: 0, opacity: 1 }} exit={{ scale: 0.4, rotate: 45, opacity: 0 }} aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            {copied ? <path d="M5 12.5l4.5 4.5L19 7" /> : <><rect x="9" y="9" width="12" height="12" rx="2" /><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" /></>}
          </motion.svg>
        </AnimatePresence>
        {copied ? "Copied" : "Copy"}
      </button>
      <span role="status" className="sr-only">{copied ? "Copied to clipboard" : ""}</span>
    </div>
  );
}
